use std::collections::{HashMap,HashSet};impl Solution{pub fn calc_equation(e:Vec<Vec<String>>,val:Vec<f64>,q:Vec<Vec<String>>)->Vec<f64>{let mut g:HashMap<String,Vec<(String,f64)>>=HashMap::new();for(i,x)in e.into_iter().enumerate(){g.entry(x[0].clone()).or_default().push((x[1].clone(),val[i]));g.entry(x[1].clone()).or_default().push((x[0].clone(),1.0/val[i]));}fn f(u:&str,t:&str,g:&HashMap<String,Vec<(String,f64)>>,v:&mut HashSet<String>)->f64{if !g.contains_key(u){return -1.0}if u==t{return 1.0}v.insert(u.into());for(x,w)in &g[u]{if !v.contains(x){let r=f(x,t,g,v);if r>0.0{return w*r}}}-1.0}q.into_iter().map(|x|f(&x[0],&x[1],&g,&mut HashSet::new())).collect()}}
